module tb_TopModule;
    logic        clk;
    logic        resetn;
    logic [1:0]  byteena;
    logic [15:0] d;
    logic [15:0] q;

    TopModule uut (
        .clk(clk),
        .resetn(resetn),
        .byteena(byteena),
        .d(d),
        .q(q)
    );

    initial begin
        clk = 0;
        forever #5 clk = ~clk;
    end

    initial begin
        resetn = 0;
        byteena = 2'b00;
        d = 16'h55AA;
        @(posedge clk);
        #1;
        if (q !== 16'h0000) begin
            $display("SELFTEST FAIL: Reset failed, q=%h", q);
            $finish;
        end

        // Release reset, byteena = 00, should stay 0
        resetn = 1;
        byteena = 2'b00;
        d = 16'h1234;
        @(posedge clk);
        #1;
        if (q !== 16'h0000) begin
            $display("SELFTEST FAIL: Hold failed when byteena=00, q=%h", q);
            $finish;
        end

        // byteena = 01 (lower byte write)
        byteena = 2'b01;
        d = 16'h1234;
        @(posedge clk);
        #1;
        if (q !== 16'h0034) begin
            $display("SELFTEST FAIL: byteena=01 failed, q=%h (expected 0034)", q);
            $finish;
        end

        // byteena = 10 (upper byte write)
        byteena = 2'b10;
        d = 16'hABCD;
        @(posedge clk);
        #1;
        if (q !== 16'hAB34) begin
            $display("SELFTEST FAIL: byteena=10 failed, q=%h (expected AB34)", q);
            $finish;
        end

        // byteena = 11 (both bytes write)
        byteena = 2'b11;
        d = 16'hFFFF;
        @(posedge clk);
        #1;
        if (q !== 16'hFFFF) begin
            $display("SELFTEST FAIL: byteena=11 failed, q=%h (expected FFFF)", q);
            $finish;
        end

        // Synchronous reset check while running
        resetn = 0;
        @(posedge clk);
        #1;
        if (q !== 16'h0000) begin
            $display("SELFTEST FAIL: Synchronous reset during run failed, q=%h", q);
            $finish;
        end

        $display("SELFTEST PASS");
        $finish;
    end
endmodule
